export function LikeButton() {
  const [likes, setLikes] = useState<number>(0);

  // تعريف دالة المعالجة وتحديد نوع الـ Event بـ TypeScript
  function handleLike(e: React.MouseEvent<HTMLButtonElement>) {
    console.log("إحداثيات النقرة:", e.clientX, e.clientY);
    setLikes((prev) => prev + 1);
  }

  return (
    <button onClick={handleLike} className="like-btn">
      إعجاب ({likes})
    </button>
  );
}

export function ItemList() {
  function handleDelete(id: number, e: React.MouseEvent<HTMLButtonElement>) {
    console.log("مسح العنصر رقم:", id);
  }

  return (
    <div>
      {/* بنستخدم Inline Arrow Function عشان نمرر الـ id ونستقبل الـ event */}
      <button onClick={(e) => handleDelete(42, e)}>
        حذف العنصر 42
      </button>
    </div>
  );
}

export function SearchInput() {
  const [query, setQuery] = useState<string>("");

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    // e.target.value هي القيمة النصية الحالية المكتوبة جوه الـ input
    setQuery(e.target.value);
  }

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={handleChange}
        placeholder="ابحث هنا..."
      />
      <p>أنت تبحث عن: {query}</p>
    </div>
  );
}

