export function ProtectedRoute({ isAuthenticated, children }: ProtectedRouteProps) {
  const location = useLocation();

  if (!isAuthenticated) {
    // توجيه لصفحة تسجيل الدخول مع حفظ الصفحة اللي كان عايز يروحها للرجوع إليها لاحقاً
