import React from "react";
import ReactDOM from "react-dom/client";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import App from "./App";

// إنشاء كائن الـ Client المركزي
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, // البيانات تعتبر طازجة لمدة 5 دقائق
      gcTime: 1000 * 60 * 30,   // الاحتفاظ بالكاش في الذاكرة لمدة 30 دقيقة
      retry: 2,                 // إعادة المحاولة مرتين تلقائياً عند فشل الشبكة
      refetchOnWindowFocus: true, // إعادة الجلب التلقائي عند العودة لتبويب المتصفح
    },
  },
});

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <App />
    </QueryClientProvider>
  </React.StrictMode>
);

