import { useQuery } from "@tanstack/react-query";

interface Product {
  id: number;
  title: string;
  price: number;
}

// دالة الجلب النقية
async function fetchProducts(): Promise<Product[]> {
  const res = await fetch("https://fakestoreapi.com/products");
  if (!res.ok) throw new Error("فشل في تحميل قائمة المنتجات");
  return await res.json();
}

export function ProductsList() {
  const { data: products, isLoading, isError, error, refetch } = useQuery({
    queryKey: ["products"], // المفتاح الفريد في الكاش
    queryFn: fetchProducts, // دالة الجلب
  });

  if (isLoading) return <p className="text-blue-500">جاري التحميل من الكاش/السيرفر...</p>;
  if (isError) return <p className="text-red-500">خطأ: {error.message}</p>;

  return (
    <div className="p-4">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold">المنتجات ({products?.length})</h2>
        <button onClick={() => refetch()} className="btn-refresh">تحديث البيانات</button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {products?.map((product) => (
          <div key={product.id} className="border p-3 rounded">
            <h3>{product.title}</h3>
            <p className="text-green-600 font-bold">${product.price}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

// src/components/AddProductForm.tsx
import React, { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";

interface NewProduct {
  title: string;
  price: number;
}

async function createProductApi(newProduct: NewProduct) {
  const res = await fetch("https://fakestoreapi.com/products", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(newProduct),
  });
  if (!res.ok) throw new Error("فشل إنشاء المنتج");
  return await res.json();
}

export function AddProductForm() {
  const [title, setTitle] = useState("");
  const [price, setPrice] = useState("");

  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: createProductApi,
    // عند نجاح العملية على السيرفر:
    onSuccess: () => {
      // إبطال كاش المنتجات القديم ليتم إعادة جلبه تلقائياً بالمنتج الجديد!
      queryClient.invalidateQueries({ queryKey: ["products"] });
      setTitle("");
      setPrice("");
      alert("تمت إضافة المنتج بنجاح وتحديث الكاش!");
    },
    onError: (err) => {
      alert(`خطأ: ${err.message}`);
    },
  });

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!title || !price) return;
    mutation.mutate({ title, price: Number(price) });
  }

  return (
    <form onSubmit={handleSubmit} className="p-4 border rounded mb-6">
      <h3 className="font-bold mb-2">إضافة منتج جديد</h3>
      <input
        type="text"
        placeholder="اسم المنتج"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        className="border p-2 rounded mr-2"
      />
      <input
        type="number"
        placeholder="السعر"
        value={price}
        onChange={(e) => setPrice(e.target.value)}
        className="border p-2 rounded mr-2"
      />
      <button
        type="submit"
        disabled={mutation.isPending}
        className="bg-green-600 text-white px-4 py-2 rounded"
      >
        {mutation.isPending ? "جاري الإرسال..." : "إضافة المنتج"}
      </button>
    </form>
  );
}

