// src/context/AuthContext.tsx
import React, { createContext, useContext, useState, useEffect, ReactNode } from "react";

export interface User {
  id: string;
  name: string;
  email: string;
  role: "user" | "admin";
}

interface AuthContextType {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  // استعادة الجلسة عند فتح التطبيق
  useEffect(() => {
    async function restoreSession() {
      try {
        const savedToken = localStorage.getItem("auth_token");
        if (savedToken) {
          // جلب بيانات المستخدم المعتمدة بالتوكن من السيرفر
          const res = await fetch("/api/auth/me", {
            headers: { Authorization: `Bearer ${savedToken}` },
          });
          if (res.ok) {
            const userData: User = await res.json();
            setUser(userData);
            setToken(savedToken);
          } else {
            // توكن غير صالح أو منتهي الصلاحية
            localStorage.removeItem("auth_token");
          }
        }
      } catch (err) {
        console.error("فشل استعادة الجلسة:", err);
      } finally {
        setIsLoading(false);
      }
    }

    restoreSession();
  }, []);

  async function login(email: string, pass: string) {
    const res = await fetch("/api/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password: pass }),
    });

    if (!res.ok) {
      throw new Error("بيانات الدخول غير صحيحة");
    }

    const data: { user: User; token: string } = await res.json();
    setUser(data.user);
    setToken(data.token);
    localStorage.setItem("auth_token", data.token);
  }

  function logout() {
    setUser(null);
    setToken(null);
    localStorage.removeItem("auth_token");
  }

  const value: AuthContextType = {
    user,
    token,
    isAuthenticated: !!user,
    isLoading,
    login,
    logout,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("يجب استخدام useAuth داخل <AuthProvider> فقط!");
  }
  return context;
}

// src/routes/ProtectedRoute.tsx
import { Navigate, useLocation } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

interface ProtectedRouteProps {
  children: JSX.Element;
  requiredRole?: "user" | "admin";
}

export function ProtectedRoute({ children, requiredRole }: ProtectedRouteProps) {
  const { user, isAuthenticated, isLoading } = useAuth();
  const location = useLocation();

  // 1. أثناء فحص الجلسة، نعرض شاشة تحميل لمنع التوجيه الخاطئ
  if (isLoading) {
    return <div className="screen-loader">جاري التحقق من هوية المستخدم...</div>;
  }

  // 2. لو لم يكن مسجل دخول، يتم توجيهه لصفحة الدخول
  if (!isAuthenticated) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // 3. لو كان المسار يتطلب صلاحيات معينة (Role Guard)
  if (requiredRole && user?.role !== requiredRole) {
    return <div className="p-8 text-center text-red-600">عفواً، ليس لديك صلاحية لدخول هذه الصفحة (Admin Only).</div>;
  }

  return children;
}

