db.products.insertOne({
  sku: "TECH-9901",
  title: "Ultra Ergonomic Desk",
  price: 450.00,
  dimensions: { width: 140, depth: 70, height: 75 }, // Embedded Sub-document
  categories: ["furniture", "office", "ergonomics"],  // Embedded Array
  stockCount: 15,
  ratings: [
    { userId: "usr_1", score: 5, comment: "Amazing build quality!" },
    { userId: "usr_2", score: 4, comment: "Good, but hard to assemble." }
  ],
  isActive: true,
  createdAt: new Date()
});

// 2. إنشاء فهارس مركبة وفهارس على المصفوفات (Multikey Index)
db.products.createIndex({ sku: 1 }, { unique: true });
db.products.createIndex({ categories: 1, price: -1 }); // Multikey + Compound Index

// 3. تعديل ذري: تقليل المخزون وإضافة تقييم جديد في نفس اللحظة
db.products.updateOne(
  { sku: "TECH-9901", stockCount: { $gt: 0 } },
  {
    $inc: { stockCount: -1 }, // خصم وحدة واحدة من المخزون
    $push: {
      ratings: {
        userId: "usr_3",
        score: 5,
        comment: "Fast shipping!",
        createdAt: new Date()
      }
    }
  }
);

// 4. خط أنابيب تجميع متقدم (Aggregation Pipeline): حساب متوسط التقييمات لكل تصنيف
db.products.aggregate([
  // المرحلة 1: تصفية المنتجات النشطة بس
  { $match: { isActive: true } },

  // المرحلة 2: تفكيك مصفوفة التصنيفات لإنشاء سجل لكل تصنيف
  { $unwind: "$categories" },

  // المرحلة 3: تفكيك مصفوفة التقييمات
  { $unwind: "$ratings" },

  // المرحلة 4: تجميع بحسب التصنيف وحساب المتوسط وإجمالي المنتجات
  {
    $group: {
      _id: "$categories",
      averageRating: { $avg: "$ratings.score" },
      totalReviewsCount: { $sum: 1 },
      totalProductsCount: { $addToSet: "$_id" }
    }
  },

  // المرحلة 5: تنسيق شكل المخرجات النهائية
  {
    $project: {
      category: "$_id",
      averageRating: { $round: ["$averageRating", 2] },
      totalReviewsCount: 1,
      uniqueProductsCount: { $size: "$totalProductsCount" },
      _id: 0
    }
  },

  // المرحلة 6: ترتيب بالتصنيف الأعلى تقييماً
  { $sort: { averageRating: -1 } }
]);

